def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    # the anchor is the 8 block (2x2, colour 8); the mover is the other object
    anchor = [o for o in objs if o["colour"] == 8][0]
    movers = [o for o in objs if o is not anchor]
    out = g.copy()

    ay0, ax0, ay1, ax1 = anchor["box"]
    for mv in movers:
        my0, mx0, my1, mx1 = mv["box"]
        dy = dx = 0
        rows_overlap = not (my1 < ay0 or ay1 < my0)
        if rows_overlap:
            # horizontal motion toward the anchor
            if mx1 < ax0:
                dx = ax0 - 1 - mx1
            else:
                dx = ax1 + 1 - mx0
        else:
            if my1 < ay0:
                dy = ay0 - 1 - my1
            else:
                dy = ay1 + 1 - my0
        # stage 1: lift the shape off the canvas
        for (y, x) in mv["cells"]:
            out[y, x] = bg
        emit(out, "Erase the colour-%d shape from its original position; it will slide toward the 8 block." % mv["colour"])
        # stage 2: place it adjacent to the anchor
        for (y, x) in mv["cells"]:
            ny, nx = y + dy, x + dx
            if 0 <= ny < out.shape[0] and 0 <= nx < out.shape[1]:
                out[ny, nx] = mv["colour"]
        emit(out, "Stamp the shape shifted by (dy=%d, dx=%d) so its bounding box touches the 8 block." % (dy, dx))
    return out
